import { useState } from "react";
import { useNavigate } from "react-router-dom";
import logo from "../logo.svg";
import "./Login.css";

function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const [error, setError] = useState("");

  const navigate = useNavigate();

  const handleLogin = async (e) => {
    e.preventDefault();

    setError("");

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL}/login`, {
        method: "POST",

        headers: {
          "Content-Type": "application/json",
        },

        credentials: "include",

        body: JSON.stringify({
          email: email,
          password: password,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        setError(data.error);
        return;
      }

      // Admin
      if (data.UserType === "Admin") {
        navigate("/admin");
      }

      // Normal user
      else {
        navigate("/user");
      }
    } catch (error) {
      setError("Unable to connect to server.");
    }
  };

  return (
    <div style={styles.page}>
      <div style={styles.card}>
        <img src={logo} alt="Job Manager logo" style={styles.logo} />
        <h1 style={styles.title}>Login</h1>

        <form onSubmit={handleLogin} style={styles.form}>
          <input
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            style={styles.input}
          />

          <input
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            style={styles.input}
          />

          <button type="submit" style={styles.primaryButton}>
            Login
          </button>
        </form>

        <button
          type="button"
          onClick={() => navigate("/register")}
          style={styles.secondaryButton}
        >
          Register
        </button>

        {error && <p style={styles.error}>{error}</p>}
      </div>
    </div>
  );
}

const styles = {
  page: {
    minHeight: "100vh",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    background: "linear-gradient(135deg, #f3f7ff 0%, #e7f0ff 100%)",
    padding: "20px",
    boxSizing: "border-box",
  },
  card: {
    width: "100%",
    maxWidth: "420px",
    background: "#ffffff",
    borderRadius: "18px",
    boxShadow: "0 16px 40px rgba(31, 66, 135, 0.12)",
    padding: "32px 28px",
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
  },
  logo: {
    width: "88px",
    height: "88px",
    marginBottom: "12px",
  },
  title: {
    margin: "0 0 20px",
    color: "#1f2d3d",
    fontSize: "2rem",
  },
  form: {
    width: "100%",
    display: "flex",
    flexDirection: "column",
    gap: "14px",
  },
  input: {
    padding: "12px 14px",
    borderRadius: "10px",
    border: "1px solid #d9e2ec",
    fontSize: "1rem",
    outline: "none",
    boxSizing: "border-box",
  },
  primaryButton: {
    marginTop: "6px",
    padding: "12px 16px",
    border: "none",
    borderRadius: "10px",
    background: "#2563eb",
    color: "#fff",
    fontSize: "1rem",
    fontWeight: 600,
    cursor: "pointer",
  },
  secondaryButton: {
    marginTop: "14px",
    width: "100%",
    padding: "12px 16px",
    border: "1px solid #c7d2fe",
    borderRadius: "10px",
    background: "#eef4ff",
    color: "#1e3a8a",
    fontSize: "1rem",
    fontWeight: 600,
    cursor: "pointer",
  },
  error: {
    marginTop: "14px",
    color: "#b91c1c",
    fontSize: "0.95rem",
  },
};

export default Login;
